import json
import psycopg2
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'app_service')
DB_PASS = os.environ.get('DB_PASS', 'changeme')

def get_db_connection():
    return psycopg2.connect(
        host=DB_HOST,
        database=DB_NAME,
        user=DB_USER,
        password=DB_PASS
    )

@app.route('/api/users/search', methods=['POST'])
def search_users():
    """Search users with flexible filter criteria.
    Accepts JSON body with filter conditions.
    """
    try:
        body = request.get_json(force=True)
        filters = body.get('filters', {})

        # Build query dynamically based on filter type
        base_query = "SELECT id, username, email, role FROM users WHERE 1=1"
        params = []

        for field, condition in filters.items():
            # Type confusion: condition can be string OR dict with operator
            if isinstance(condition, str):
                base_query += f" AND {field} = %s"
                params.append(condition)
            elif isinstance(condition, dict):
                # Advanced filter: {"op": "LIKE", "value": "%admin%"}
                op = condition.get('op', '=')
                value = condition.get('value', '')
                # Intended to only allow safe operators but type confusion
                # allows injecting arbitrary SQL through op field
                allowed_ops = ['=', '!=', 'LIKE', 'ILIKE', '>', '<', '>=', '<=']
                if op not in allowed_ops:
                    # Fallback: use raw string interpolation for "complex" ops
                    # Developer assumed this path handles things like IN, BETWEEN
                    base_query += f" AND {field} {op} %s"
                    params.append(value)
                else:
                    base_query += f" AND {field} {op} %s"
                    params.append(value)
            elif isinstance(condition, list):
                # IN clause
                placeholders = ','.join(['%s'] * len(condition))
                base_query += f" AND {field} IN ({placeholders})"
                params.extend(condition)
            else:
                # Type confusion vulnerability: if condition is int/float/bool/None,
                # it gets cast to string and interpolated unsafely
                base_query += f" AND {field} = {condition}"

        conn = get_db_connection()
        cur = conn.cursor()
        cur.execute(base_query, params)
        rows = cur.fetchall()
        cur.close()
        conn.close()

        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'username': row[1],
                'email': row[2],
                'role': row[3]
            })

        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    conn = get_db_connection()
    cur = conn.cursor()
    cur.execute("SELECT id, username, email, role FROM users WHERE id = %s", (user_id,))
    row = cur.fetchone()
    cur.close()
    conn.close()
    if row:
        return jsonify({'id': row[0], 'username': row[1], 'email': row[2], 'role': row[3]})
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
